-- Replace the complete New Lens card library with the 2026-08-25 rewrite.
-- Source: New_Lens_Content_11_Themes_60_Cards_Rewritten.xlsx
-- User theme cursors are intentionally preserved: every theme still uses
-- stable sort orders 1-60, so the next card remains deterministic.

begin;

delete from public.lens_cards;


do $$
declare
  v_total integer;
begin
  select count(*) into v_total from public.lens_cards;
  if v_total <> 660 then
    raise exception 'New Lens rewrite expected 660 cards, found %', v_total;
  end if;

  if exists (
    select 1
    from public.lens_cards
    group by theme
    having count(*) <> 60 or min(sort_order) <> 1 or max(sort_order) <> 60
  ) then
    raise exception 'New Lens rewrite requires exactly 60 ordered cards per theme';
  end if;

  if (select count(distinct theme) from public.lens_cards) <> 11
     or exists (
       select 1 from public.lens_cards
       where theme <> all (array['expression', 'awareness', 'momentum', 'direction', 'steadiness', 'confidence', 'gratitude', 'connection', 'comparison', 'fear_of_wrong', 'running_empty']::text[])
     ) then
    raise exception 'New Lens rewrite contains an unexpected theme set';
  end if;
end;
$$;

commit;
