insert into public.lens_cards (theme, sort_order, headline, body) values
  ('expression', 1, 'A feeling can be real without being the whole truth.', 'Holding things in deserves attention, but it does not get the final word on what is possible, what you are worth, or what must happen next.'),
  ('expression', 2, 'This is a state you are in, not a definition of who you are.', 'The mind often turns a difficult pattern into an identity. Holding things in describes your current experience; it does not describe your permanent character.'),
  ('expression', 3, 'A signal is not the same as an instruction.', 'Holding things in may be pointing to a need for safe, honest expression. You can listen to the signal without obeying every conclusion that comes with it.'),
  ('expression', 4, '“I don’t know yet” is often more accurate than the harshest answer.', 'For this struggle, one safe piece of truth is more useful than continued silence. When certainty is missing, the mind tends to fill the gap quickly. Leaving the question open can be wiser than turning uncertainty into a negative verdict about yourself.'),
  ('expression', 5, 'Familiar does not mean permanent.', 'Expression can be gradual; honesty does not require emotional overexposure. A response can become automatic through repetition, but repetition is not destiny. Noticing the pattern earlier already creates a small space in which a different response can begin.'),
  ('expression', 6, 'The loudest thought is not automatically the most important one.', 'Intensity can make one interpretation feel authoritative. Before following it, ask whether it is useful, supported, and aligned with honesty.'),
  ('expression', 7, 'Feeling bad is not proof that you are moving in the wrong direction.', 'For this struggle, one safe piece of truth is more useful than continued silence. Some honest or necessary shifts feel uncomfortable before they feel relieving. Discomfort can be part of change without being evidence that the change is wrong.'),
  ('expression', 8, 'You do not need a perfect explanation before your experience is allowed.', 'Understanding can help, but it is not an entry requirement for responding kindly. You can acknowledge holding things in before you know exactly where it came from.'),
  ('expression', 9, 'A thought does not become evidence by repeating itself.', 'The aim is not to say everything, but to stop abandoning every true thing you feel. Repetition creates familiarity, and familiarity can feel like truth. Ask what new information the thought is adding before giving it more authority.'),
  ('expression', 10, 'Your first interpretation is only one possible interpretation.', 'For this struggle, one safe piece of truth is more useful than continued silence. The mind prefers a quick story to an open question. Place the first story beside two other plausible explanations before deciding what the current experience means about you.'),
  ('expression', 11, 'The whole problem may be too large; the next useful piece is not.', 'Expression can be gradual; honesty does not require emotional overexposure. You do not have to solve the entire experience at once. Focus on the smallest part that can be named, changed, tested, or supported today.'),
  ('expression', 12, 'You only need the next honest step, not the entire route.', 'Trying to see the whole path can make movement impossible. Name one true sentence is enough to create information for whatever comes after it.'),
  ('expression', 13, 'A reversible choice does not need permanent-level certainty.', 'For this struggle, one safe piece of truth is more useful than continued silence. Before demanding a perfect answer, ask whether the next step can be adjusted. If it can, a careful experiment may be more useful than extended hesitation.'),
  ('expression', 14, 'Ten percent lighter is still meaningfully lighter.', 'Expression can be gradual; honesty does not require emotional overexposure. Relief does not have to be complete to count. A small reduction in pressure can create enough room to think more clearly and choose more deliberately.'),
  ('expression', 15, 'A pause can be an action, not an absence of action.', 'The aim is not to say everything, but to stop abandoning every true thing you feel. Stopping briefly can interrupt an automatic pattern and restore choice. The value of a pause is not inactivity; it is the chance to respond instead of react.'),
  ('expression', 16, '“Enough for today” is a valid boundary.', 'For this struggle, one safe piece of truth is more useful than continued silence. Today does not need to carry the full solution. It only needs a response that respects what matters and the capacity that actually exists now.'),
  ('expression', 17, 'Progress can begin before it becomes visible.', 'Expression can be gradual; honesty does not require emotional overexposure. Noticing a pattern sooner, recovering faster, or choosing one different sentence may look small. Those changes often appear before the larger result does.'),
  ('expression', 18, 'A reset is not the same as starting from zero.', 'What you have learned remains available even after a hard day. Returning to honesty uses experience; it does not erase it.'),
  ('expression', 19, 'Consistency means returning, not never slipping.', 'For this struggle, one safe piece of truth is more useful than continued silence. A difficult moment does not cancel the direction you are building. The ability to come back is often a more realistic measure of growth than perfect steadiness.'),
  ('expression', 20, 'A minimum can protect what an ideal keeps postponing.', 'When the ideal response feels unreachable, choose the smallest version that still serves honesty. A workable floor is often more useful than an admired ceiling.'),
  ('expression', 21, 'Not everything affecting you is asking to be controlled.', 'The aim is not to say everything, but to stop abandoning every true thing you feel. Some parts need action, some need acceptance, and some need time. Separating those categories can keep uncontrollable pieces from consuming all your attention.'),
  ('expression', 22, 'What is still true matters as much as what feels uncertain.', 'For this struggle, one safe piece of truth is more useful than continued silence. A difficult state narrows attention toward what is missing or unstable. Deliberately naming what remains reliable gives the mind a fuller picture to work with.'),
  ('expression', 23, 'You may not control the feeling, but you can influence the response.', 'Expression can be gradual; honesty does not require emotional overexposure. Choice often returns in a smaller form than expected: where attention goes, what gets postponed, what is said, or which next step is made gentler.'),
  ('expression', 24, 'A boundary is a way of protecting capacity for what matters.', 'The aim is not to say everything, but to stop abandoning every true thing you feel. Limits are not evidence of failure or lack of care. They make it more possible to show up with honesty instead of continuing from resentment or depletion.'),
  ('expression', 25, 'You do not need permission to respond to what you already know.', 'For this struggle, one safe piece of truth is more useful than continued silence. If something repeatedly costs you peace, energy, or self-respect, that information matters. You can take it seriously before anyone else agrees with your interpretation.'),
  ('expression', 26, 'Support does not make the insight less yours.', 'Another person can offer perspective, structure, or company without taking over your choice. Asking for help can be part of honesty, not evidence that you lack it.'),
  ('expression', 27, 'Not every weight you notice belongs entirely to you.', 'The aim is not to say everything, but to stop abandoning every true thing you feel. Before carrying more, separate what is yours to influence from what belongs to another person, a larger system, or simple uncertainty.'),
  ('expression', 28, 'Attention is a limited resource, not an unlimited obligation.', 'For this struggle, one safe piece of truth is more useful than continued silence. You do not have to give every thought equal time. Directing attention toward what is useful is not avoidance; it is choosing what gets to shape the day.'),
  ('expression', 29, 'Sometimes the answer is less, not a better way to carry more.', 'Expression can be gradual; honesty does not require emotional overexposure. Optimization has limits. If the total demand is the problem, a more efficient response may still leave too much. Reduction can be the wiser intervention.'),
  ('expression', 30, 'A pattern is shaped by its surroundings, not only by willpower.', 'The aim is not to say everything, but to stop abandoning every true thing you feel. Instead of judging yourself for repeating it, notice what keeps cueing or rewarding it. Changing one condition can make a different response easier to access.'),
  ('expression', 31, 'Your fear deserves a seat at the table, not every seat.', 'For this struggle, one safe piece of truth is more useful than continued silence. Let concern contribute information, then invite evidence, values, capacity, and past experience into the decision too. A fuller table usually produces a fairer answer.'),
  ('expression', 32, 'One hard moment should not outweigh the longer pattern.', 'Expression can be gradual; honesty does not require emotional overexposure. The mind often treats the newest difficulty as the most representative one. Zoom out far enough to include what you have handled, learned, and repaired before.'),
  ('expression', 33, 'Separate what happened from what your mind concluded.', 'The aim is not to say everything, but to stop abandoning every true thing you feel. Write the observable facts in one sentence and the interpretation in another. That small separation can reveal where choice, uncertainty, or another explanation still exists.'),
  ('expression', 34, 'The future version of you may judge this moment by kindness, not perfection.', 'For this struggle, one safe piece of truth is more useful than continued silence. Imagine looking back with more distance. The wiser question may be whether you responded honestly and sustainably, not whether you removed every uncertainty.'),
  ('expression', 35, 'Look for the moments when the pattern loosens.', 'Expression can be gradual; honesty does not require emotional overexposure. Exceptions reveal conditions that help. Even a brief easing can show what support, environment, timing, or perspective makes a difference.'),
  ('expression', 36, 'Changing the sentence can change the size of the problem.', 'The aim is not to say everything, but to stop abandoning every true thing you feel. Replace “always,” “never,” or “everything” with language that is specific to this moment. Accuracy often feels less dramatic, but it gives you more room to act.'),
  ('expression', 37, 'What you want and what you fear can both be present.', 'For this struggle, one safe piece of truth is more useful than continued silence. Fear can be loud without being the deepest preference. Naming the desire separately prevents caution from quietly becoming the only voice in the decision.'),
  ('expression', 38, 'Avoiding discomfort has a cost too.', 'The comparison is rarely between discomfort and no discomfort. It is often between the short discomfort of name one true sentence and the longer cost of leaving the pattern untouched.'),
  ('expression', 39, 'You can test a new response without turning it into a lifelong rule.', 'The aim is not to say everything, but to stop abandoning every true thing you feel. Choose one small experiment and observe what changes. Information gathered from a real attempt is often more trustworthy than predictions made from inside the same loop.'),
  ('expression', 40, '“Enough” needs a definition or it will keep moving.', 'For this struggle, one safe piece of truth is more useful than continued silence. An undefined standard can never be reached. Decide what a reasonable, humane version of enough looks like for this moment before measuring yourself against it.'),
  ('expression', 41, 'You are more likely to change through understanding than through contempt.', 'Harshness may create urgency, but it often reduces clarity. Curiosity about why holding things in developed can reveal a more workable path forward.'),
  ('expression', 42, 'A need is not a character flaw.', 'Needing safe, honest expression does not make you weak, difficult, or behind. It gives you useful information about the conditions under which you function more fully.'),
  ('expression', 43, 'Your worth does not rise and fall with today’s capacity.', 'For this struggle, one safe piece of truth is more useful than continued silence. Output, certainty, closeness, and composure can vary. None of them is a reliable daily measurement of how much value you have as a person.'),
  ('expression', 44, 'Uncertainty is not the same as incapability.', 'Expression can be gradual; honesty does not require emotional overexposure. You can be unsure and still thoughtful, careful, or capable. Confidence is one internal feeling; competence is a broader pattern of how you respond and adapt.'),
  ('expression', 45, 'Caring deeply can make the problem feel louder.', 'The intensity of holding things in may partly reflect how much the underlying need matters. Let care clarify your values instead of turning it into evidence that you failed.'),
  ('expression', 46, 'Replace “What is wrong with me?” with “What is this trying to protect?”', 'For this struggle, one safe piece of truth is more useful than continued silence. Many difficult patterns began as protection. Understanding the protection does not mean keeping the pattern; it helps you design a safer replacement.'),
  ('expression', 47, 'One honest sentence can be more useful than a complete explanation.', 'Expression can be gradual; honesty does not require emotional overexposure. You do not have to organize the whole experience before responding. Start with the simplest thing you know to be true, then let clarity build from there.'),
  ('expression', 48, 'Not knowing can be a stage of learning, not a failure to decide.', 'The aim is not to say everything, but to stop abandoning every true thing you feel. Some clarity arrives only after attention, rest, conversation, or experience. Allowing an honest “not yet” can prevent a rushed answer from pretending to be wisdom.'),
  ('expression', 49, 'The sustainable version is often the wiser version.', 'For this struggle, one safe piece of truth is more useful than continued silence. A response that works once through force may not be the best response. Prefer the version you can repeat without abandoning your health, honesty, or self-respect.'),
  ('expression', 50, 'Low capacity changes what a problem looks like.', 'Expression can be gradual; honesty does not require emotional overexposure. Before reaching a permanent conclusion, consider whether rest, space, or support would change the picture. A depleted mind should not have to issue every final verdict.'),
  ('expression', 51, 'Two truths can exist without canceling each other.', 'The aim is not to say everything, but to stop abandoning every true thing you feel. You can want change and feel afraid, care and need space, appreciate something and still want more. Complexity is not hypocrisy; it is often accuracy.'),
  ('expression', 52, 'Honesty does not require total disclosure.', 'For this struggle, one safe piece of truth is more useful than continued silence. The mind may frame the options as extremes. Look for a both-and response that honors the real need without demanding an unnecessary opposite.'),
  ('expression', 53, 'The right action does not always arrive with the right feeling.', 'Expression can be gradual; honesty does not require emotional overexposure. You may still feel uncertain, tired, exposed, or afraid while taking a wise step. Internal comfort is helpful, but it is not the only evidence available.'),
  ('expression', 54, 'Clarity can arrive after the pressure to have it.', 'The aim is not to say everything, but to stop abandoning every true thing you feel. The absence of an immediate answer is not proof that no answer exists. Reducing urgency can make room for information that pressure was crowding out.'),
  ('expression', 55, 'Action can create clarity that thought alone cannot.', 'When reflection stops producing new information, name one true sentence. A small real-world response can reveal what another round of analysis cannot.'),
  ('expression', 56, 'When certainty is unavailable, values can still give direction.', 'Ask which response is more aligned with honesty, even if neither feels perfect. Values can guide a next step without pretending to predict the outcome.'),
  ('expression', 57, 'Ask what would make this ten percent more workable.', 'The aim is not to say everything, but to stop abandoning every true thing you feel. A smaller question lowers the pressure to transform everything. The answer may be a boundary, a pause, a clearer sentence, a reduced demand, or one piece of support.'),
  ('expression', 58, 'One thing can be released before everything is resolved.', 'For this struggle, one safe piece of truth is more useful than continued silence. You may be able to release a deadline, an imagined audience, an impossible standard, or one unnecessary demand. Relief can begin before the larger situation ends.'),
  ('expression', 59, 'The next kind step can still be a strong step.', 'Kindness is not the same as avoidance. Name one true sentence can protect what matters while refusing the idea that progress must be punishing to count.'),
  ('expression', 60, 'This moment does not need a final verdict.', 'Holding things in may be important, but it is still one moment in a longer process. Respond to what is needed now without turning today into a permanent conclusion.'),
  ('awareness', 1, 'A feeling can be real without being the whole truth.', 'Overthinking deserves attention, but it does not get the final word on what is possible, what you are worth, or what must happen next.'),
  ('awareness', 2, 'This is a state you are in, not a definition of who you are.', 'The mind often turns a difficult pattern into an identity. Overthinking describes your current experience; it does not describe your permanent character.'),
  ('awareness', 3, 'A signal is not the same as an instruction.', 'Overthinking may be pointing to a need for clarity and mental space. You can listen to the signal without obeying every conclusion that comes with it.'),
  ('awareness', 4, '“I don’t know yet” is often more accurate than the harshest answer.', 'For this struggle, clarity grows when possibilities stop being treated as facts. When certainty is missing, the mind tends to fill the gap quickly. Leaving the question open can be wiser than turning uncertainty into a negative verdict about yourself.'),
  ('awareness', 5, 'Familiar does not mean permanent.', 'Thinking is useful until it stops producing new information and starts recycling fear. A response can become automatic through repetition, but repetition is not destiny. Noticing the pattern earlier already creates a small space in which a different response can begin.'),
  ('awareness', 6, 'The loudest thought is not automatically the most important one.', 'Intensity can make one interpretation feel authoritative. Before following it, ask whether it is useful, supported, and aligned with clear attention.'),
